CREATE DATABASE IF NOT EXISTS biblioteca CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE biblioteca;
CREATE TABLE Categories (CategoryId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(100) NOT NULL, IsActive BOOLEAN NOT NULL DEFAULT TRUE, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT UQ_Categories_Name UNIQUE (Name)) ENGINE=InnoDB;
CREATE TABLE Books (BookId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, Title VARCHAR(200) NOT NULL, Isbn13 CHAR(13) NOT NULL, CategoryId BIGINT UNSIGNED NOT NULL, IsArchived BOOLEAN NOT NULL DEFAULT FALSE, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UpdatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT UQ_Books_Isbn13 UNIQUE (Isbn13), CONSTRAINT FK_Books_Categories FOREIGN KEY (CategoryId) REFERENCES Categories(CategoryId), CONSTRAINT CK_Books_Isbn13 CHECK (Isbn13 REGEXP '^[0-9]{13}$')) ENGINE=InnoDB;
CREATE TABLE Authors (AuthorId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(150) NOT NULL, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT UQ_Authors_Name UNIQUE (Name)) ENGINE=InnoDB;
CREATE TABLE BookAuthors (BookId BIGINT UNSIGNED NOT NULL, AuthorId BIGINT UNSIGNED NOT NULL, PRIMARY KEY (BookId, AuthorId), CONSTRAINT FK_BookAuthors_Books FOREIGN KEY (BookId) REFERENCES Books(BookId), CONSTRAINT FK_BookAuthors_Authors FOREIGN KEY (AuthorId) REFERENCES Authors(AuthorId)) ENGINE=InnoDB;
CREATE TABLE Copies (CopyId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, BookId BIGINT UNSIGNED NOT NULL, InventoryCode VARCHAR(40) NOT NULL, Status ENUM('AVAILABLE','LOANED','MAINTENANCE','LOST') NOT NULL DEFAULT 'AVAILABLE', CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT UQ_Copies_InventoryCode UNIQUE (InventoryCode), CONSTRAINT FK_Copies_Books FOREIGN KEY (BookId) REFERENCES Books(BookId), INDEX IX_Copies_Book_Status (BookId, Status)) ENGINE=InnoDB;
CREATE TABLE Readers (ReaderId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, FullName VARCHAR(150) NOT NULL, RegistrationNumber VARCHAR(30) NOT NULL, IsSuspended BOOLEAN NOT NULL DEFAULT FALSE, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT UQ_Readers_RegistrationNumber UNIQUE (RegistrationNumber), INDEX IX_Readers_Name (FullName)) ENGINE=InnoDB;
CREATE TABLE Loans (LoanId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, CopyId BIGINT UNSIGNED NOT NULL, ReaderId BIGINT UNSIGNED NOT NULL, LoanedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, DueAt DATETIME NOT NULL, ReturnedAt DATETIME NULL, CONSTRAINT FK_Loans_Copies FOREIGN KEY (CopyId) REFERENCES Copies(CopyId), CONSTRAINT FK_Loans_Readers FOREIGN KEY (ReaderId) REFERENCES Readers(ReaderId), CONSTRAINT CK_Loans_Dates CHECK (DueAt > LoanedAt AND (ReturnedAt IS NULL OR ReturnedAt >= LoanedAt)), INDEX IX_Loans_Copy_Active (CopyId, ReturnedAt), INDEX IX_Loans_Reader_Active (ReaderId, ReturnedAt), INDEX IX_Loans_Due_Returned (DueAt, ReturnedAt)) ENGINE=InnoDB;
